import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=`/assets/weight-BiCYk5GF.png`,a=JSON.parse(`{"path":"/ML/test.html","title":"Test","lang":"en-US","frontmatter":{},"git":{"updatedTime":1615746745000,"contributors":[{"name":"Noei","username":"Noei","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/Noei"}],"changelog":[{"hash":"65466cdbf81e444a3c55aea49f6acbabf34bd61a","time":1615746745000,"email":"logmanxsa@gmail.com","author":"Noei","message":"ML test content"}]},"filePathRelative":"ML/test.md"}`),o={name:`test.md`};function s(r,a,o,s,c,l){return n(),t(`div`,null,[...a[0]||=[e(`<h1 id="test" tabindex="-1"><a class="header-anchor" href="#test"><span>Test</span></a></h1><ul><li>องค์ประกอบของ ML</li><li>มี case ให้ ให้เลือกวิธีการเรียนรู้ (algorithm) ของ ML มาใช้</li><li>Neural network คำนวณ weight รอบที่ 1</li><li>ขั้นตอนการเรียนรู้ภาษาธรรมชาติ</li><li>top-down parser</li><li>องค์ประกอบระบบผู้เชี่ยวชาญ</li><li>อธิบายหลักการพัฒนาระบบผู้เชี่ยวชาญจาก case ที่กำหนดให้</li></ul><ol><li>องค์ประกอบของ ML</li></ol><ul><li>DATA ข้อมูล</li><li>ALGORITHM ขั้นตอนวิธี</li><li>FEATURES คุณสมบัติ 2.ประเภทการเรียนรู้ของ ML</li><li>Classical Learning = การสอนMเพื่อแก้ปัญหาทางคณิตศาสตร์ อย่างเช่น ค้นหารูป แบบตัวเลขประเมินความใกล้เคียงของข้อมูล และคำนวณทิศทางของเวกเตอร์ เป็นต้น -Supervised = ML เรียนรู้โดยที่มีอาจารย์สอน ที่คอยให้คำตอบ <ul><li>Classification = เป็นการพยายามที่จะทำนายคำตอบที่ไม่ต่อเนื่องกัน ไม่มีการอ้างอิงกับ อะไรเลย</li><li>Regression = เป็นการพยายามที่จะทำนายคำตอบที่ต่อเนื่องกัน เช่น การคาดการณ์ราคา หุ้น -Unsupervised = ML เรียนรู้โดยไม่มีคนสอน</li><li>Clustering = กระบวนการจัดระเบียบวัตถุเป็นกลุ่มที่มีสมาชิกคล้ายคลึงกันในทางใดทางหนึ่ง</li><li>Dimensionality reduction = เป็นการลดจำนวนมิติเพื่อบีบอัดข้อมูล ทำให้เราไม่จำเป็น ต้องเก็บข้อมูลไว้ครบ</li><li>Association rule learning = การหาความสัมพันธ์ของข้อมูล</li></ul></li><li>Reinforcement Learning = เทคนิคการทำปัญญาประดิษฐ์ (Artificial Intelligence) ที่ใช้วิธีการให้รางวัล (reward) หรือลงโทษ (punishment) เพื่อที่จะขับเคลื่อนให้ agent นั้นๆ ไปในทิศทางเป้าหมายที่ระบุไว้ได้</li><li>Ensemble Method = เทคนิคที่สร้างแบบจำลองหลาย ๆ แบบแล้วรวมเข้าด้วยกันเพื่อ ให้ได้ผลลัพธ์ที่ดีขึ้น</li><li>Neural Network And Deep Learning = วิธีการเรียนรู้แบบอัตโนมัติด้วยการ เลียนแบบ การทำงานของโครงข่ายประสาทของมนุษย์ (Neurons) โดยนำระบบโครงข่ายประสาท (Neural Network) มาซ้อนกัน หลายชั้น (Layer) และทำการเรียนรู้ข้อมูลตัวอย่าง</li></ul><ol start="3"><li>Neural network หา weight (วาดรูป)<br><a href="https://projects.invisionapp.com/freehand/document/kDlX4sEjS" target="_blank" rel="noopener noreferrer">Freehand</a><img src="`+i+`" alt="Weight"></li><li>ขั้นตอนการเรียนรู้ภาษาธรรมชาติ (Natural Language)</li></ol><ul><li>Phonological ศึกษาการออกเสียง</li><li>Morphological Analysis ศึกษาหน่วยของคำ</li><li>Syntactical Analysis วิเคราะห์ทางไวยากรณ์</li><li>Semantic Analysis วิเคราะห์และแสดงความหมาย</li><li>Discourse Integration ตรวจคำ(pronoun)ที่อ้างอิงระหว่างประโยคว่าหมายถึง noun ตัวใด</li><li>Pragmatic Analysis ตรวจความหมายที่แท้จริงของประโยค</li></ul><ol start="5"><li>top-down parser ...</li><li>องค์ประกอบระบบผู้เชี่ยวชาญ (วาดรูปง่ายมาก)</li></ol><ul><li>Human Expert ผู้เชี่ยวชาญ</li><li>Knowledge Engineer ผู้ที่มีความรู้ความสามารถในศาสตร์แห่งการสร้างตรรกะขั้นสูง ในระบบคอมพิวเตอร์เพื่อพยายามจำลองการตัดสินใจของมนุษย์และงานด้านความรู้ความ เข้าใจระดับสูง (ผู้ที่พัฒนาระบบ Dev)</li><li>Knowledge Base ฐานความรู้</li><li>Inference Engine เครื่องมืออนุมาน ทำหน้าที่คำนวณหาผลลัพธ์จากข้อเท็จจริงและ ข้อมูลสนเทศที่ได้เก็บเอาไว้แล้ว</li><li>User Interface ส่วนต่อประสานระหว่าง user กับ สินค้าหรือบริการ</li><li>User ผู้ใช้สินค้าหรือบริการ 7.อธิบาย&lt;หลักการพัฒนาระบบผู้เชี่ยวชาญ&gt;จาก case ที่กำหนดให้ ขั้นตอนการพัฒนา ES</li><li>ระบุโดเมนที่เป็นปัญหา <ul><li>ปัญหาต้องเหมาะสำหรับระบบผู้เชี่ยวชาญในการแก้ปัญหา</li><li>ค้นหาผู้เชี่ยวชาญในโดเมนงานสำหรับโครงการ ES</li><li>สร้างความคุ้มทุนของระบบ</li></ul></li><li>ออกแบบระบบ <ul><li>ระบุเทคโนโลยี ES</li><li>รู้และกำหนดระดับของการทำงานร่วมกับระบบและฐานข้อมูลอื่น ๆ</li><li>ตระหนักถึงวิธีที่แนวคิดสามารถแสดงถึงความรู้เกี่ยวกับโดเมนได้ดีที่สุด</li></ul></li><li>พัฒนา Prototype <ul><li>จากฐานความรู้: วิศวกรความรู้ทำงานเพื่อรับความรู้เกี่ยวกับโดเมนจากผู้เชี่ยวชาญ</li><li>แสดงในรูปแบบของกฎ If-THEN-ELSE</li></ul></li><li>พัฒนาและดำเนินการ ES <ul><li>ทดสอบและตรวจสอบการทำงานร่วมกันของ ES กับองค์ประกอบทั้งหมดของสภาพแวด ล้อมรวมถึงผู้ใช้ปลายทางฐานข้อมูลและระบบข้อมูลอื่น ๆ</li><li>จัดทำเอกสารโครงการ ES ให้ดี</li><li>ฝึกผู้ใช้ให้ใช้ ES</li></ul></li><li>บำรุงรักษาระบบ <ul><li>อัปเดตฐานความรู้ให้ทันสมัยอยู่เสมอโดยการตรวจสอบและอัปเดตเป็นประจำ</li><li>รองรับอินเทอร์เฟซใหม่กับระบบข้อมูลอื่น ๆ ตามที่ระบบเหล่านั้นพัฒนาขึ้น</li></ul></li></ul>`,8)]])}var c=r(o,[[`render`,s]]);export{a as _pageData,c as default};